"""Apply consistent navigation and production copy to static editorial pages."""
import re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
NAV='''<nav id="primary-nav" class="primary-nav" aria-label="Primary navigation"><a href="/emergencies/">Get help now</a><a href="/library/">Browse subjects</a><a href="/preparedness/">Prepare</a><a href="/topics/">A–Z index</a><a href="/resources/">Downloads & sources</a><a class="nav-cta" href="/search/">Search</a></nav>'''
for p in [ROOT/'templates/shell.html',*ROOT.rglob('*.html')]:
 if any(x in p.parts for x in ['.git','dist','node_modules']) or p.name=='indexv3.html':continue
 s=p.read_text()
 s=re.sub(r'<nav id="primary-nav".*?</nav>',NAV,s,flags=re.S)
 s=re.sub(r'<script src="/ads\.js[^"]*"[^>]*></script>\s*', '', s)
 s=s.replace('</head>', '<script src="/ads.js?v=oz8" async></script>\n</head>')
 s=s.replace('FIELD KNOWLEDGE / V1.0','CIVILIAN KNOWLEDGE / FREE ACCESS')
 s=s.replace('When an emergency is active, follow local official instructions.','Act on danger. Verify information. Plan for help to be unavailable.')
 s=re.sub(r'/(styles.css|app.js|search.js)\?v=oz\d+',lambda m:'/'+m[1]+'?v=oz7',s)
 if p==ROOT/'index.html':
  s=re.sub(r'<form class="library-search hero-search".*?</form>','',s,flags=re.S)
  s=s.replace('Practical knowledge for emergencies, everyday disruptions, and the places beyond the pavement. Find what matters, understand it quickly, and keep learning.','Practical steps for individuals and families when power, water, communications or outside help fail. Find the quick answer, make a workable plan and keep the essentials offline.')
  s=s.replace('Current local alerts and emergency instructions always take priority.','Built for people who may have to manage without outside help.')
  s=s.replace('Contact local emergency services. Follow current instructions from local authorities.','Take the first protective step now. Seek qualified help when reachable and safe; do not wait for a response to get out of danger.')
  s=s.replace('Find official sources','Find trusted references')
  s=s.replace('Choose a situation. Open an answer-first Osprey Zero guide. Current instructions for your location always come first.','Search what is happening, or choose a common situation. Every guide leads with the immediate action and includes a plan for when help is unavailable.')
  s=s.replace('Search power, storm, water, evacuation…','Search all topics: power, water, shelter…')
  s=s.replace('Save a checklist, open official guidance, then read the steps and exceptions.','Save the checklist, follow practical steps and read the limits. Independent and official references are there when you need deeper context.')
  s=s.replace('Check local alerts and urgent medical needs. Use battery light, keep the fridge closed, and run generators only outdoors away from openings.','Prioritise urgent medical power, safe temperature and drinking water. Use battery light, keep the fridge closed and keep generators outdoors at least 20 feet from openings.')
  s=s.replace('The 72-hour blackout field guide is in development. Join the early list and we’ll email you when it is ready. Short, practical, and designed to be useful when you have little time to spare.','The online blackout guides and checklists are free now. Join the early list for the upcoming extended printable field guide; access to emergency information never requires signup.')
  s=s.replace('Government guidance, public health references, and published field manuals have a separate source library for deeper reading and current instructions.','Independent humanitarian guidance, public health references and published field manuals provide deeper context. The practical action plan lives here and does not assume official help will arrive.')
  marker='    <section class="guide-method"'
  paths='''<section class="wrap mission-paths" aria-label="Common needs"><div><p class="kicker">WHEN SYSTEMS FAIL</p><h2>Find a workable plan.</h2></div><a href="/library/conflict/">Conflict & civilian safety</a><a href="/emergencies/long-blackout/">Days without power</a><a href="/library/evacuation-shelter/">Leaving home & staying together</a><a href="/library/utilities/">Water & sanitation</a><a href="/topics/">Every topic A–Z</a></section>'''
  s=re.sub(r'<section class="wrap mission-paths".*?</section>','',s,flags=re.S)
  s=s.replace(marker,paths+'\n'+marker)
 if p==ROOT/'about/index.html':
  s=s.replace('Our aim is to help people find a clear next step and develop lasting capability.','Our mission is to help individuals and families make practical decisions when services fail, assistance is unavailable or authorities are unsafe to approach. Civilian safety, family continuity and self-reliance guide the library.')
  s=s.replace('Guides will carry sources, review dates, scope, and a clear place for current local instructions.','Guides carry linked sources, update dates and clear limits. We distinguish protective guidance from household planning and do not claim independent clinical or specialist certification.')
  s=s.replace('The field library is being developed now. Join the Field Notes list for guide releases and practical updates.','The encyclopedia and its printable checklists are free to read without an account. Join Field Notes if you would like updates; email signup never unlocks emergency information.')
 if p==ROOT/'privacy/index.html':
  start=s.index('>',s.index('<main id="main"'))+1
  end=s.index('  </main>',start)
  s=s[:start]+'''<section class="wrap library-heading"><p class="kicker">PRIVACY & ADVERTISING</p><h1>Your information. Your choice.</h1><p>Updated 2 October 2026. Emergency guides and downloads are free and do not require an account.</p></section><section class="wrap interior-section"><div class="prose"><h2>Search stays in your browser</h2><p>Osprey Zero ranks a downloaded search index locally. We do not send searches to an Osprey Zero search service. Typed queries are not added to the URL. Incoming shared search links may contain query text and can remain in browser history or hosting logs. Avoid entering names, addresses or other sensitive personal details.</p><h2>Email signup</h2><p>The optional early-access and newsletter forms request an email address. Netlify processes and stores submitted form data for the site operator. This release collects signup requests; automated newsletter delivery is not configured by this update. Never put emergency reports or personal safety information in a signup form. To stop future messages, use the unsubscribe method in any email you receive.</p><h2>Ads and third-party services</h2><p>Browsing, preparedness and field-guide pages automatically load Monetag advertising to support the free library. Ads may use cookies, browser storage, IP addresses and device information for delivery, measurement and fraud prevention. The vignette zone may display a dismissible advertising overlay. The separate push zone can offer advertising notifications on browsing hubs; it requires browser permission. Advertising is separate from our guidance and is not an endorsement.</p><p>The homepage, search, urgent response pages, privacy page and signup confirmation do not initialise ad zones. On other eligible pages, third-party ad code loads automatically, using the vignette zone. Browsing hubs also load a separate push-subscription zone. Disaster-scam and information-verification articles are eligible reading pages; other emergency articles stay ad-free. There is currently no site control to disable ads and no paid ad-free plan. Ad appearance and frequency are controlled by the provider and browser.</p><p>Push notifications require browser permission. If you have previously allowed advertising notifications, revoke that permission in your browser’s site settings; the uploaded advertising service worker is not an offline guide cache or an emergency alert service.</p><p><a href="https://monetag.com/privacy-policy/" target="_blank" rel="noopener noreferrer">Monetag privacy information</a> · <a href="https://www.netlify.com/privacy/" target="_blank" rel="noopener noreferrer">Netlify privacy information</a></p><h2>Browser storage and hosting</h2><p>Osprey Zero no longer reads or saves the former focus-mode and advertising-session preferences. Advertising providers may use their own cookies and browser storage. Netlify may retain request and security logs. The site also uses externally hosted Google Fonts and links to outside references; those services have their own privacy practices.</p><h2>Safer browsing in a crisis</h2><p>Do not share live family locations or sensitive identity information through public links. Saving a checklist before an outage reduces your reliance on a network. For a rights or privacy concern, seek a trusted local legal or independent support channel when safe.</p></div></section>\n'''+s[end:]
 if p==ROOT/'thanks/index.html':
  s=re.sub(r'<p>[^<]*(?:email|list|inbox)[^<]*</p>','<p>Your signup request has been submitted. The emergency library and checklists are available now; email delivery is not immediate.</p>',s,count=1,flags=re.I)
 p.write_text(s)
